/**
 * The demo catalogue: real networks and supplier prices from the reference
 * price list, the real supplier zones, and three demo zones built only from
 * priced networks (generated by scripts/build-networks.ts).
 */
import raw from "./seed/catalogue.json";
import type { Network } from "@/lib/platform/coverage";

export type CatalogueZone = {
  id: string;
  name: string;
  source: "supplier" | "demo";
  demoZone: boolean;
  networkIds: string[];
  missingTadigs: string[];
};

export const CATALOGUE = raw as unknown as { networks: Network[]; zones: CatalogueZone[] };

export const NETWORK_BY_ID = new Map(CATALOGUE.networks.map((n) => [n.id, n]));
export const ZONE_BY_ID = new Map(CATALOGUE.zones.map((z) => [z.id, z]));

export function zoneNetworks(zoneId: string): Network[] {
  return (ZONE_BY_ID.get(zoneId)?.networkIds ?? []).map((id) => NETWORK_BY_ID.get(id)!).filter(Boolean);
}
